/**
 * Before/after comparison of a design change.
 *
 * Pure and deterministic: every number comes from the two building models and the
 * cost engine's estimates for them. Nothing here is estimated, rounded for effect or
 * generated by AI — it is what a reviewer needs to approve or reject a change.
 */
import type { BuildingModel } from "@/domain/model/types";
import type { CostEstimate } from "@/domain/cost/engine";
import type { Quantities } from "@/domain/model/quantities";
import { validateModel } from "@/domain/model/validate";

export interface Snapshot { model: BuildingModel; estimate: CostEstimate }

export interface QuantityDiff { key: string; label: string; unit: string; before: number; after: number; delta: number }
export interface RoomDiff { id: string; name: string; level: string; before: number | null; after: number | null; delta: number }
export interface LineDiff { id: string; label: string; unit: string; quantityBefore: number; quantityAfter: number; costBefore: number; costAfter: number; delta: number }

export interface Comparison {
  currency: string;
  cost: {
    before: { low: number; high: number; expected: number };
    after: { low: number; high: number; expected: number };
    /** after − before, mid-point */
    delta: number;
    deltaPct: number;
  };
  grossFloorArea: { before: number; after: number; delta: number };
  rooms: RoomDiff[];
  quantities: QuantityDiff[];
  /** Cost lines whose mid-point amount changed, largest change first */
  lines: LineDiff[];
  /** Model check on the proposed design */
  checks: { valid: boolean; errors: string[]; warnings: string[] };
  /** Data provenance of the prices used */
  dataStatus: string;
}

const QUANTITIES: { key: keyof Quantities; label: string; unit: string }[] = [
  { key: "grossFloorArea", label: "Gross floor area", unit: "m²" },
  { key: "footprintArea", label: "Footprint", unit: "m²" },
  { key: "finishedFloorArea", label: "Finished floor area", unit: "m²" },
  { key: "exteriorWallNetArea", label: "External walls (net of openings)", unit: "m²" },
  { key: "interiorWallArea", label: "Internal walls", unit: "m²" },
  { key: "paintArea", label: "Internal paint", unit: "m²" },
  { key: "roofArea", label: "Roof", unit: "m²" },
  { key: "windowArea", label: "Windows", unit: "m²" },
  { key: "windowCount", label: "Windows", unit: "count" },
  { key: "interiorDoorCount", label: "Internal doors", unit: "count" },
  { key: "bedrooms", label: "Bedrooms", unit: "count" },
  { key: "bathrooms", label: "Bathrooms", unit: "count" },
  { key: "kitchenRunLength", label: "Kitchen run", unit: "m" },
];

const r2 = (n: number) => Math.round(n * 100) / 100;
const mid = (r: [number, number]) => (r[0] + r[1]) / 2;
/** Treat sub-centimetre / sub-cent floating noise as no change. */
const changed = (a: number, b: number, eps = 0.005) => Math.abs(a - b) > eps;

export function compareSnapshots(before: Snapshot, after: Snapshot): Comparison {
  const eb = before.estimate, ea = after.estimate;
  if (eb.currency !== ea.currency) throw new Error("Cannot compare estimates in different currencies.");

  const costB = { low: r2(eb.total[0]), high: r2(eb.total[1]), expected: r2(eb.expected) };
  const costA = { low: r2(ea.total[0]), high: r2(ea.total[1]), expected: r2(ea.expected) };

  // Rooms, matched by id (ids are stable across operations; renamed rooms keep their id).
  const roomsOf = (m: BuildingModel) => new Map(m.levels.flatMap((l) => l.rooms.map((r) => [r.id, { r, level: l.name }] as const)));
  const rb = roomsOf(before.model), ra = roomsOf(after.model);
  const rooms: RoomDiff[] = [];
  for (const id of new Set([...rb.keys(), ...ra.keys()])) {
    const b = rb.get(id), a = ra.get(id);
    const areaB = b ? r2(b.r.area) : null, areaA = a ? r2(a.r.area) : null;
    if (areaB !== null && areaA !== null && !changed(areaB, areaA) && b!.r.name === a!.r.name) continue;
    rooms.push({ id, name: (a ?? b)!.r.name, level: (a ?? b)!.level, before: areaB, after: areaA, delta: r2((areaA ?? 0) - (areaB ?? 0)) });
  }
  rooms.sort((x, y) => Math.abs(y.delta) - Math.abs(x.delta) || x.name.localeCompare(y.name));

  const qb = eb.quantities, qa = ea.quantities;
  const quantities: QuantityDiff[] = QUANTITIES
    .map(({ key, label, unit }) => ({ key, label, unit, before: r2(qb[key] as number), after: r2(qa[key] as number) }))
    .filter((q) => changed(q.before, q.after))
    .map((q) => ({ ...q, delta: r2(q.after - q.before) }));

  const lb = new Map(eb.lines.map((l) => [l.id, l])), la = new Map(ea.lines.map((l) => [l.id, l]));
  const lines: LineDiff[] = [];
  for (const id of new Set([...lb.keys(), ...la.keys()])) {
    const b = lb.get(id), a = la.get(id);
    const costBefore = b ? r2(mid(b.amount)) : 0, costAfter = a ? r2(mid(a.amount)) : 0;
    if (!changed(costBefore, costAfter, 0.5)) continue;
    lines.push({
      id, label: a && b && a.label !== b.label ? `${b.label} → ${a.label}` : (a ?? b)!.label, unit: (a ?? b)!.unit,
      quantityBefore: b ? r2(b.quantity) : 0, quantityAfter: a ? r2(a.quantity) : 0,
      costBefore, costAfter, delta: r2(costAfter - costBefore),
    });
  }
  lines.sort((x, y) => Math.abs(y.delta) - Math.abs(x.delta) || x.id.localeCompare(y.id));

  const report = validateModel(after.model);
  const delta = r2(costA.expected - costB.expected);
  return {
    currency: ea.currency,
    cost: { before: costB, after: costA, delta, deltaPct: costB.expected ? r2((delta / costB.expected) * 100) : 0 },
    grossFloorArea: { before: r2(eb.grossFloorArea), after: r2(ea.grossFloorArea), delta: r2(ea.grossFloorArea - eb.grossFloorArea) },
    rooms,
    quantities,
    lines,
    checks: {
      valid: report.valid,
      errors: report.issues.filter((i) => i.severity === "error").map((i) => i.message),
      warnings: report.issues.filter((i) => i.severity === "warning").map((i) => i.message),
    },
    dataStatus: ea.dataStatus,
  };
}
